"use client";
import { usePlatform } from "./use-platform.js";
import { useCallback } from "react";
import { formatHotkey } from "@zag-js/hotkeys";
//#region src/providers/hotkeys/use-format-hotkey.ts
var useFormatHotkey = () => {
	const platform = usePlatform();
	return useCallback((hotkey, options = {}) => formatHotkey(hotkey, {
		platform,
		...options
	}), [platform]);
};
//#endregion
export { useFormatHotkey };
